164	class FeatureCardCanvasRuntime {
165	  private _instances: FeatureCardCanvasInstance[] = [];
166	  private _rafId: number | null = null;
167	  private _resizeListener: (() => void) | null = null;
168	
169	  init(root?: ParentNode | null): void {
170	    this.dispose();
171	    const scope = root ?? document;
172	    const cardList = scope.querySelector<HTMLElement>(
173	      FEATURE_CARD_CANVAS.listSelector,
174	    );
175	    if (!cardList) return;
176	    const canvasElements = Array.from(
177	      cardList.querySelectorAll<HTMLCanvasElement>(
178	        FEATURE_CARD_CANVAS.canvasSelector,
179	      ),
180	    );
181	    if (canvasElements.length === 0) return;
182	
183	    this._instances = canvasElements.flatMap((canvas, index) => {
184	      const context = canvas.getContext("2d");
185	      if (!context) return [];
186	      return [
187	        {
188	          canvas,
189	          context,
190	          size: { width: 0, height: 0, dpr: 1 },
191	          rotation: index * 0.45,
192	          tilt: 0.6 + index * 0.18,
193	          speed:
194	            FEATURE_CARD_CANVAS.rotationSpeedBase +
195	            index * FEATURE_CARD_CANVAS.rotationSpeedStep,
196	          particles: this._createParticles(index),
197	        },
198	      ];
199	    });
200	
201	    if (this._instances.length === 0) return;
202	
203	    this._resizeListener = () => this._resize();
204	    window.addEventListener("resize", this._resizeListener);
205	    this._resize();
206	    this._startLoop();
207	  }
208	
209	  dispose(): void {
210	    if (this._rafId !== null) {
211	      FrameScheduler.cancel(this._rafId);
212	      this._rafId = null;
213	    }
214	    if (this._resizeListener) {
215	      window.removeEventListener("resize", this._resizeListener);
216	      this._resizeListener = null;
217	    }
218	    this._instances = [];
219	  }
220	
221	  private _startLoop(): void {
222	    const render = (): void => {
223	      this._render();
224	      this._rafId = FrameScheduler.request(render);
225	    };
226	    render();
227	  }
228	
229	  private _resize(): void {
230	    const dpr = Math.min(
231	      ResponsiveRuntime.getDefault().getSnapshot().render.clampedPixelRatio,
232	      FEATURE_CARD_CANVAS.pixelRatioMax,
233	    );
234	    this._instances.forEach((instance) => {
235	      const bounds = instance.canvas.getBoundingClientRect();
236	      const width = Math.max(1, Math.round(bounds.width));
237	      const height = Math.max(1, Math.round(bounds.height));
238	      instance.size = { width, height, dpr };
239	      instance.canvas.width = Math.round(width * dpr);
240	      instance.canvas.height = Math.round(height * dpr);
241	      instance.context.setTransform(dpr, 0, 0, dpr, 0, 0);
242	    });
243	  }
244	
245	  private _render(): void {
246	    this._instances.forEach((instance) => {
247	      const { context, size } = instance;
248	      if (size.width <= 0 || size.height <= 0) return;
249	
250	      instance.rotation += instance.speed;
251	      context.clearRect(0, 0, size.width, size.height);
252	      context.fillStyle = FEATURE_CARD_CANVAS.clearColor;
253	      context.fillRect(0, 0, size.width, size.height);
254	
255	      this._drawParticles(instance);
256	      this._drawCube(instance);
257	    });
258	  }
259	
260	  private _drawParticles(instance: FeatureCardCanvasInstance): void {
261	    const { context, size, rotation, particles } = instance;
262	    const halfWidth = size.width * 0.5;
263	    const halfHeight = size.height * 0.5;
264	    const scale =
265	      Math.min(size.width, size.height) * FEATURE_CARD_CANVAS.cubeScale;
266	
267	    context.fillStyle = FEATURE_CARD_CANVAS.particleColor;
268	    particles.forEach((particle) => {
269	      const spin = rotation * (0.6 + particle.drift * 0.4);
270	      const cos = Math.cos(spin);
271	      const sin = Math.sin(spin);
272	      const rotatedX = particle.x * cos - particle.z * sin;
273	      const rotatedZ = particle.x * sin + particle.z * cos;
274	      const depth = rotatedZ + 3.6;
275	      const perspective = 1 / depth;
276	      const drawX = halfWidth + rotatedX * scale * perspective;
277	      const drawY =
278	        halfHeight +
279	        (particle.y + Math.sin(rotation + particle.drift) * 0.14) *
280	          scale *
281	          perspective;
282	      const drawSize = particle.size * perspective * 4.5;
283	      context.fillRect(drawX, drawY, drawSize, drawSize);
284	    });
285	  }
286	
287	  private _drawCube(instance: FeatureCardCanvasInstance): void {
288	    const { context, size, rotation, tilt } = instance;
289	    const halfWidth = size.width * 0.5;
290	    const halfHeight = size.height * 0.5;
291	    const scale =
292	      Math.min(size.width, size.height) * FEATURE_CARD_CANVAS.cubeScale;
293	    const projected = FEATURE_CARD_CUBE_VERTICES.map(([x, y, z]) => {
294	      const rotatedY = this._rotateY(x, z, rotation);
295	      const rotatedX = this._rotateX(y, rotatedY.z, tilt);
296	      const depth = rotatedX.z + 4.2;
297	      const perspective = 1 / depth;
298	      return {
299	        x: halfWidth + rotatedY.x * scale * perspective,
300	        y: halfHeight + rotatedX.y * scale * perspective,
301	      };
302	    });
303	
304	    context.fillStyle = FEATURE_CARD_CANVAS.fillStyle;
305	    context.beginPath();
306	    context.moveTo(projected[4].x, projected[4].y);
307	    context.lineTo(projected[5].x, projected[5].y);
308	    context.lineTo(projected[6].x, projected[6].y);
309	    context.lineTo(projected[7].x, projected[7].y);
310	    context.closePath();
311	    context.fill();
312	
313	    context.strokeStyle = FEATURE_CARD_CANVAS.strokeStyle;
314	    context.lineWidth = 1.2;
315	    FEATURE_CARD_CUBE_EDGES.forEach(([startIndex, endIndex]) => {
316	      const start = projected[startIndex];
317	      const end = projected[endIndex];
318	      context.beginPath();
319	      context.moveTo(start.x, start.y);
320	      context.lineTo(end.x, end.y);
321	      context.stroke();
322	    });
323	  }
324	
325	  private _createParticles(index: number): FeatureCardCanvasParticle[] {
326	    return Array.from(
327	      { length: FEATURE_CARD_CANVAS.particleCount },
328	      (_, particleIndex) => {
329	        const seed = (index + 1) * (particleIndex + 3);
330	        const angle = seed * 0.73;
331	        const radius = 1.2 + (particleIndex % 5) * 0.18;
332	        return {
333	          x: Math.cos(angle) * radius,
334	          y: (((particleIndex % 7) - 3) / 3) * 1.35,
335	          z: Math.sin(angle) * radius,
336	          size:
337	            FEATURE_CARD_CANVAS.particleSizeMin +
338	            (particleIndex % 4) *
339	              ((FEATURE_CARD_CANVAS.particleSizeMax -
340	                FEATURE_CARD_CANVAS.particleSizeMin) /
341	                3),
342	          drift: 0.8 + (particleIndex % 6) * 0.12,
343	        };
344	      },
345	    );
346	  }
347	
348	  private _rotateY(
349	    x: number,
350	    z: number,
351	    angle: number,
352	  ): { x: number; z: number } {
353	    const cos = Math.cos(angle);
354	    const sin = Math.sin(angle);
355	    return {
356	      x: x * cos - z * sin,
357	      z: x * sin + z * cos,
358	    };
359	  }
360	
361	  private _rotateX(
362	    y: number,
363	    z: number,
364	    angle: number,
365	  ): { y: number; z: number } {
366	    const cos = Math.cos(angle);
367	    const sin = Math.sin(angle);
368	    return {
369	      y: y * cos - z * sin,
370	      z: y * sin + z * cos,
371	    };
372	  }
373	}
