375	export class PageRuntime {
376	  private controller: PageController | null = null;
377	  private bootTask: Promise<void> | null = null;
378	  private readonly _globalUiRuntime = new PageGlobalUiRuntime();
379	  private readonly _featureCardCanvasRuntime = new FeatureCardCanvasRuntime();
380	  private readonly _subpageStarfieldRuntime = new SubpageStarfieldRuntime();
381	
382	  async runPage(root?: HTMLElement): Promise<void> {
383	    if (this.bootTask) return this.bootTask;
384	
385	    this.bootTask = (async () => {
386	      this._disposePageRuntime();
387	      this.disposeController();
388	
389	      if ("scrollRestoration" in history) {
390	        history.scrollRestoration = "manual";
391	      }
392	      window.scrollTo({ top: 0, behavior: "auto" });
393	
394	      this._globalUiRuntime.init(root);
395	      this._featureCardCanvasRuntime.init(root);
396	      this._subpageStarfieldRuntime.init(root);
397	
398	      this.controller = new PageController();
399	      await this.controller.init(root);
400	    })().finally(() => {
401	      this.bootTask = null;
402	    });
403	
404	    return this.bootTask;
405	  }
406	
407	  syncAfterContainerChange(): void {
408	    this._globalUiRuntime.syncAfterContainerChange();
409	  }
410	
411	  disposeController(): void {
412	    this.controller?.dispose();
413	    this.controller = null;
414	    this.bootTask = null;
415	    TimelineRuntime.clear();
416	  }
417	
418	  dispose(): void {
419	    this.disposeController();
420	    this._disposePageRuntime();
421	    TimelineRuntime.clear();
422	  }
423	
424	  private _disposePageRuntime(): void {
425	    try {
426	      this._globalUiRuntime.dispose();
427	    } catch (error) {
428	      console.warn(
429	        "[PageRuntime._disposePageRuntime] Global UI cleanup failed.",
430	        error,
431	      );
432	    }
433	    try {
434	      this._featureCardCanvasRuntime.dispose();
435	    } catch (error) {
436	      console.warn(
437	        "[PageRuntime._disposePageRuntime] Feature card canvas cleanup failed.",
438	        error,
439	      );
440	    }
441	    try {
442	      this._subpageStarfieldRuntime.dispose();
443	    } catch (error) {
444	      console.warn(
445	        "[PageRuntime._disposePageRuntime] Subpage starfield cleanup failed.",
446	        error,
447	      );
448	    }
449	  }
450	}
